with department_stats as (select dept_id, max(salary) - min(salary) salary_range, max(salary) max_salary from employees group by dept_id) select departments.id, departments.dept_name, departments.location, department_stats.salary_range, department_stats.max_salary from departments left outer join department_stats on departments.id = department_stats.dept_id where department_stats.max_salary >= 107000 order by departments.location, max_salary desc
